/**
 * Site-wide definitions. On each page the first use of each term in the article
 * text is underlined and shows its definition on hover or focus (scripts/terms.ts);
 * /glossary/ lists them all. Matching is case-sensitive and on whole words; list
 * other spellings in `aliases`. Keep each definition to a sentence or two
 * (lint: at most 280 characters).
 */
export interface GlossaryEntry {
  /** Anchor on /glossary/ (lowercase, dashes). */
  id: string;
  term: string;
  aliases?: string[];
  definition: string;
  /** Further reading: official docs first, then other references. */
  links?: { label: string; href: string }[];
}

export const GLOSSARY: GlossaryEntry[] = [
  { id: 'haproxy', term: 'HAProxy', definition: 'An open-source TCP/HTTP load balancer and proxy. It health-checks its backend servers and only sends traffic to the ones that pass.' },
  { id: 'ecmp', term: 'ECMP', definition: 'Equal-cost multi-path routing: when several routes to a destination are equally good, the router spreads connections across all of them.' },
  { id: 'anycast', term: 'anycast', definition: 'One IP address announced from several machines at once; the network delivers each connection to one of them.' },
  { id: 'vip', term: 'VIP', definition: 'Virtual IP: an address that is not tied to one machine and can move between, or be shared by, several of them.' },
  { id: 'bgp', term: 'BGP', definition: 'Border Gateway Protocol: how routers exchange which IP prefixes are reachable through whom. kube-vip uses it to announce a VIP.' },
  { id: 'kube-vip', term: 'kube-vip', definition: 'A Kubernetes component that provides a virtual IP for the cluster, announcing it with ARP or BGP from the nodes that hold it.' },
  { id: 'cephfs', term: 'CephFS', definition: 'The POSIX file system of the Ceph distributed storage system; many clients can mount and share the same files.' },
  { id: 'pvc', term: 'PVC', aliases: ['PersistentVolumeClaim'], definition: 'PersistentVolumeClaim: a Kubernetes request for storage that a Pod mounts; it binds to a PersistentVolume.' },
  { id: 'rwx', term: 'RWX', aliases: ['ReadWriteMany'], definition: 'ReadWriteMany: a volume access mode in which many nodes can mount the same volume read-write at once.' },
  { id: 'daemonset', term: 'DaemonSet', definition: 'A Kubernetes workload that runs one copy of a Pod on every node (or every matching node).' },
  { id: 'sidecar', term: 'sidecar', definition: 'A helper container that runs next to the main container in the same Pod, sharing its network and volumes.' },
  { id: 'readiness-probe', term: 'readiness probe', aliases: ['Readiness'], definition: 'A Kubernetes check of whether a container should receive traffic. When it fails, the Pod is marked NotReady and taken out of Service endpoints, but not restarted.' },
  { id: 'liveness-probe', term: 'liveness probe', aliases: ['Liveness'], definition: 'A Kubernetes check of whether a container is still working. When it fails repeatedly, the kubelet kills and restarts the container.' },
  { id: 'kubelet', term: 'kubelet', definition: 'The agent on each Kubernetes node that starts and watches the Pods scheduled there and runs their probes.' },
  { id: 'containerd', term: 'containerd', definition: 'The container runtime that pulls images and runs containers on each node; it can try a list of registry mirrors in order.' },
  { id: 'helm', term: 'Helm', definition: 'The Kubernetes package manager: it renders a chart (templates plus values) into objects and installs or upgrades them as a release.' },
  { id: 'argo-cd', term: 'Argo CD', aliases: ['Argo'], definition: 'A GitOps controller that keeps a cluster in sync with manifests in Git, applying and pruning objects as Git changes.' },
  { id: 'statefulset', term: 'StatefulSet', definition: 'A Kubernetes workload for Pods that need stable names and storage, such as databases or a registry with per-replica state.' },
  { id: 'thanos', term: 'Thanos', definition: 'A system that extends Prometheus with long-term storage and a global query view; its Ruler evaluates alerting rules.' },
  { id: 'fsync', term: 'fsync', definition: 'A system call that blocks until a file’s data is written to the storage device, so a hung mount makes it hang too.' },
  // GPUs, Kubernetes GPU stack and LLM inference (Learn pages).
  { id: 'gpu', term: 'GPU', aliases: ['GPUs'], definition: 'Graphics processing unit: a chip with thousands of small cores and its own fast memory, used for graphics, AI training and LLM inference.', links: [{ label: 'Wikipedia', href: 'https://en.wikipedia.org/wiki/Graphics_processing_unit' }, { label: 'Learn: What a GPU is', href: '/learn/what-is-a-gpu/' }] },
  { id: 'hbm', term: 'HBM', definition: 'High Bandwidth Memory: DRAM stacked next to the GPU die, several TB/s. An MI355X has 288 GB.', links: [{ label: 'Wikipedia', href: 'https://en.wikipedia.org/wiki/High_Bandwidth_Memory' }] },
  { id: 'vram', term: 'VRAM', definition: 'The GPU’s own memory (HBM on datacenter GPUs). Tools report how much each process holds.' },
  { id: 'cu', term: 'CU', aliases: ['Compute Unit'], definition: 'Compute Unit: AMD’s compute block inside a GPU; NVIDIA calls it an SM. MI355X has 256.' },
  { id: 'sm', term: 'SM', aliases: ['Streaming Multiprocessor'], definition: 'Streaming Multiprocessor: NVIDIA’s compute block inside a GPU; AMD calls it a CU.' },
  { id: 'xgmi', term: 'XGMI', aliases: ['Infinity Fabric'], definition: 'AMD’s GPU-to-GPU link (Infinity Fabric). The 8 GPUs of an MI355X server form one XGMI hive.' },
  { id: 'hive', term: 'hive', definition: 'AMD: a set of GPUs joined by XGMI. Also a fault domain: a reset of one MI35x GPU can reset the whole 8-GPU hive.' },
  { id: 'nvlink', term: 'NVLink', definition: 'NVIDIA’s GPU-to-GPU link. NVSwitch chips join many GPUs into one NVLink domain (72 in an NVL72 rack).', links: [{ label: 'NVIDIA', href: 'https://www.nvidia.com/en-us/data-center/nvlink/' }] },
  { id: 'nvswitch', term: 'NVSwitch', definition: 'NVIDIA switch chip for NVLink. HGX boards and NVL72 switch trays use it; it needs Fabric Manager on the host.' },
  { id: 'fabric-manager', term: 'Fabric Manager', definition: 'NVIDIA host service that configures NVSwitch routing. Its version must match the GPU driver exactly.', links: [{ label: 'NVIDIA guide', href: 'https://docs.nvidia.com/datacenter/tesla/fabric-manager-user-guide/' }] },
  { id: 'rocm', term: 'ROCm', definition: 'AMD’s open GPU software platform: HIP runtime, compilers, math and collective libraries, amd-smi.', links: [{ label: 'ROCm docs', href: 'https://rocm.docs.amd.com/en/latest/' }] },
  { id: 'hip', term: 'HIP', definition: 'AMD’s C++ GPU programming API, close to CUDA; code can be ported between them.', links: [{ label: 'HIP docs', href: 'https://rocm.docs.amd.com/projects/HIP/en/latest/' }] },
  { id: 'cuda', term: 'CUDA', definition: 'NVIDIA’s GPU programming platform and runtime. libcuda belongs to the driver; the toolkit ships in containers.', links: [{ label: 'CUDA docs', href: 'https://docs.nvidia.com/cuda/' }] },
  { id: 'rccl', term: 'RCCL', definition: 'ROCm Communication Collectives Library: AMD’s version of NCCL, for all-reduce and similar across GPUs.', links: [{ label: 'GitHub', href: 'https://github.com/ROCm/rccl' }] },
  { id: 'nccl', term: 'NCCL', definition: 'NVIDIA Collective Communications Library: fast data exchange (all-reduce, all-gather) between GPUs.', links: [{ label: 'GitHub', href: 'https://github.com/NVIDIA/nccl' }] },
  { id: 'amdgpu', term: 'amdgpu', definition: 'The AMD GPU Linux kernel driver. Datacenter hosts usually install it as the amdgpu-dkms package, built by DKMS for the running kernel.' },
  { id: 'kfd', term: 'KFD', definition: 'Kernel Fusion Driver: the compute part of amdgpu. Its device file /dev/kfd is given to every GPU container.' },
  { id: 'dkms', term: 'DKMS', definition: 'Dynamic Kernel Module Support: rebuilds an out-of-tree kernel module (like amdgpu) for each installed kernel.' },
  { id: 'amd-smi', term: 'amd-smi', definition: 'AMD’s GPU command-line tool and library: inventory, metrics, processes, topology, RAS, partitions. Replaces rocm-smi.', links: [{ label: 'AMD SMI docs', href: 'https://rocm.docs.amd.com/projects/amdsmi/en/latest/' }] },
  { id: 'nvidia-smi', term: 'nvidia-smi', definition: 'NVIDIA’s GPU command-line tool: inventory, utilization, processes, ECC, MIG, NVLink and topology.', links: [{ label: 'NVIDIA docs', href: 'https://docs.nvidia.com/deploy/nvidia-smi/' }] },
  { id: 'dcgm', term: 'DCGM', definition: 'NVIDIA Data Center GPU Manager: health checks, diagnostics (dcgmi diag) and metrics; dcgm-exporter feeds Prometheus.', links: [{ label: 'DCGM docs', href: 'https://docs.nvidia.com/datacenter/dcgm/latest/' }, { label: 'dcgm-exporter', href: 'https://github.com/NVIDIA/dcgm-exporter' }] },
  { id: 'rvs', term: 'RVS', definition: 'ROCm Validation Suite: AMD stress and validation tests for GPUs.', links: [{ label: 'RVS docs', href: 'https://rocm.docs.amd.com/projects/ROCmValidationSuite/en/latest/' }] },
  { id: 'agfhc', term: 'AGFHC', definition: 'AMD GPU Field Health Check: AMD’s long-running hardware diagnostic (about 6 hours). Used for burn-in and before RMA.' },
  { id: 'xid', term: 'Xid', definition: 'An NVIDIA driver error code printed to the kernel log, e.g. Xid 79 (GPU fell off the bus) or 48 (double-bit ECC).', links: [{ label: 'Xid catalog', href: 'https://docs.nvidia.com/deploy/xid-errors/' }] },
  { id: 'ecc', term: 'ECC', definition: 'Error-correcting code memory. Correctable errors are fixed silently; uncorrectable ones corrupt data and usually need a reset.' },
  { id: 'ras', term: 'RAS', definition: 'Reliability, availability, serviceability: the hardware error reporting (ECC, fatal events) that amdgpu logs and amd-smi reads.' },
  { id: 'mig', term: 'MIG', aliases: ['Multi-Instance GPU'], definition: 'NVIDIA Multi-Instance GPU: splits one GPU into up to 7 hardware-isolated instances.', links: [{ label: 'MIG guide', href: 'https://docs.nvidia.com/datacenter/tesla/mig-user-guide/' }] },
  { id: 'spx', term: 'SPX', aliases: ['CPX', 'DPX', 'QPX'], definition: 'AMD compute partition modes. SPX: all compute dies as one GPU. CPX: each die is its own GPU.' },
  { id: 'nps', term: 'NPS1', aliases: ['NPS2', 'NPS'], definition: 'AMD memory partition modes (NUMA per socket). NPS1: one pool of HBM per GPU.' },
  { id: 'dra', term: 'DRA', aliases: ['Dynamic Resource Allocation'], definition: 'Dynamic Resource Allocation: the Kubernetes API that lets a driver publish devices and the scheduler give a Pod a specific one through a ResourceClaim.', links: [{ label: 'Kubernetes docs', href: 'https://kubernetes.io/docs/concepts/scheduling-eviction/dynamic-resource-allocation/' }, { label: 'Learn: GPU allocation', href: '/learn/k8s-gpu-allocation/' }] },
  { id: 'resourceclaim', term: 'ResourceClaim', aliases: ['ResourceClaims'], definition: 'DRA object: a request for devices. Its status records the allocated device and the Pod using it.', links: [{ label: 'Kubernetes docs', href: 'https://kubernetes.io/docs/concepts/scheduling-eviction/dynamic-resource-allocation/' }] },
  { id: 'resourceclaimtemplate', term: 'ResourceClaimTemplate', definition: 'DRA object: a pattern for claims; Kubernetes makes one ResourceClaim per Pod from it.' },
  { id: 'resourceslice', term: 'ResourceSlice', aliases: ['ResourceSlices'], definition: 'DRA object a driver publishes per node: the devices it has and their attributes.' },
  { id: 'deviceclass', term: 'DeviceClass', definition: 'DRA object naming a kind of device by a selector. The AMD driver\'s is gpu.amd.com.' },
  { id: 'device-plugin', term: 'device plugin', definition: 'The older Kubernetes way to expose devices: a node agent advertises a count (e.g. amd.com/gpu: 8).', links: [{ label: 'Kubernetes docs', href: 'https://kubernetes.io/docs/concepts/extend-kubernetes/compute-storage-net/device-plugins/' }] },
  { id: 'cdi', term: 'CDI', definition: 'Container Device Interface: a JSON/YAML spec telling the runtime which device files, mounts and env to add to a container.', links: [{ label: 'CDI spec', href: 'https://github.com/cncf-tags/container-device-interface' }] },
  { id: 'gpu-operator', term: 'GPU operator', aliases: ['GPU Operator'], definition: 'A controller that installs per-node GPU software as DaemonSets from one custom resource (AMD DeviceConfig, NVIDIA ClusterPolicy).', links: [{ label: 'AMD GPU Operator', href: 'https://instinct.docs.amd.com/projects/gpu-operator/en/latest/' }, { label: 'NVIDIA GPU Operator', href: 'https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/' }] },
  { id: 'deviceconfig', term: 'DeviceConfig', definition: 'The AMD GPU Operator custom resource. It selects nodes and turns each operand on or off.' },
  { id: 'clusterpolicy', term: 'ClusterPolicy', definition: 'The NVIDIA GPU Operator custom resource that turns driver, toolkit, device plugin, DCGM and others on or off.' },
  { id: 'nfd', term: 'NFD', aliases: ['Node Feature Discovery'], definition: 'Node Feature Discovery: labels nodes with hardware features. GPU operators can use its labels to select GPU nodes.', links: [{ label: 'NFD docs', href: 'https://kubernetes-sigs.github.io/node-feature-discovery/' }] },
  { id: 'kmm', term: 'KMM', definition: 'Kernel Module Management: an operator that builds and loads kernel modules in containers. An alternative to installing the driver on the host.', links: [{ label: 'KMM docs', href: 'https://kmm.sigs.k8s.io/' }] },
  { id: 'npd', term: 'NPD', aliases: ['node-problem-detector'], definition: 'node-problem-detector: a node agent that turns health checks and kernel-log patterns into node conditions.', links: [{ label: 'GitHub', href: 'https://github.com/kubernetes/node-problem-detector' }] },
  { id: 'taint', term: 'taint', aliases: ['taints', 'NoSchedule'], definition: 'A node mark that repels Pods without a matching toleration. NoSchedule keeps new Pods off; NoExecute also evicts.', links: [{ label: 'Kubernetes docs', href: 'https://kubernetes.io/docs/concepts/scheduling-eviction/taint-and-toleration/' }] },
  { id: 'cordon', term: 'cordon', definition: 'Marking a node unschedulable (spec.unschedulable). Running Pods stay; only a person uncordons.' },
  { id: 'rdma', term: 'RDMA', definition: 'Remote Direct Memory Access: a NIC reads or writes another machine’s memory without its CPU copying the data.' },
  { id: 'roce', term: 'RoCE', definition: 'RDMA over Converged Ethernet: RDMA on an Ethernet network. Common for GPU-to-GPU traffic between servers.', links: [{ label: 'Wikipedia', href: 'https://en.wikipedia.org/wiki/RDMA_over_Converged_Ethernet' }] },
  { id: 'multus', term: 'Multus', definition: 'A CNI plugin that gives a Pod extra network interfaces, each described by a NetworkAttachmentDefinition (NAD).', links: [{ label: 'GitHub', href: 'https://github.com/k8snetworkplumbingwg/multus-cni' }] },
  { id: 'nad', term: 'NAD', aliases: ['NetworkAttachmentDefinition'], definition: 'NetworkAttachmentDefinition: a Multus object describing one extra network.' },
  { id: 'hca', term: 'HCA', definition: 'Host Channel Adapter: an RDMA-capable NIC. Pods ask for one as rdma/hca_devices.' },
  { id: 'prefill', term: 'prefill', definition: 'The first phase of LLM inference: read the whole prompt in one parallel pass and build the KV cache.', links: [{ label: 'Learn: inference basics', href: '/learn/llm-inference-basics/' }] },
  { id: 'decode', term: 'decode', definition: 'The second phase of LLM inference: generate output one token at a time.' },
  { id: 'kv-cache', term: 'KV cache', definition: 'Per-layer keys and values for every token seen so far; prefill builds it and decode reads it each step.', links: [{ label: 'PagedAttention paper', href: 'https://arxiv.org/abs/2309.06180' }] },
  { id: 'disagg', term: 'disaggregated inference', definition: 'Running prefill and decode on separate pools of hardware and moving the KV cache between them, so each phase can be sized and tuned on its own (DistServe, Splitwise).', links: [{ label: 'DistServe paper', href: 'https://arxiv.org/abs/2401.09670' }] },
  { id: 'speculative-decoding', term: 'speculative decoding', definition: 'A small draft model guesses tokens; the large target model verifies them in one pass.', links: [{ label: 'Paper', href: 'https://arxiv.org/abs/2211.17192' }] },
  { id: 'vllm', term: 'vLLM', definition: 'An open-source LLM serving engine. Its engine runs as VLLM::EngineCore processes.', links: [{ label: 'vLLM docs', href: 'https://docs.vllm.ai/' }] },
  { id: 'mooncake', term: 'Mooncake', definition: 'An open-source KV-cache store and transfer engine for LLM serving that pools KV cache across machines and moves it between prefill and decode workers.', links: [{ label: 'GitHub', href: 'https://github.com/kvcache-ai/Mooncake' }] },
  { id: 'mi355x', term: 'MI355X', aliases: ['MI355', 'MI350X'], definition: 'AMD Instinct MI355X: CDNA 4 datacenter GPU with 288 GB HBM3E. Usually 8 per server.', links: [{ label: 'AMD Instinct docs', href: 'https://instinct.docs.amd.com/' }] },
  { id: 'nvl72', term: 'NVL72', definition: 'NVIDIA rack with 72 Blackwell GPUs and 36 Grace CPUs joined by NVLink switch trays into one domain; arm64.', links: [{ label: 'NVIDIA GB300 NVL72', href: 'https://www.nvidia.com/en-us/data-center/gb300-nvl72/' }] },
  { id: 'imex', term: 'IMEX', definition: 'NVIDIA service that lets GPUs in different trays of an NVLink domain share memory; NVIDIA DRA exposes it as a ComputeDomain.', links: [{ label: 'IMEX guide', href: 'https://docs.nvidia.com/multi-node-nvlink-systems/imex-guide/' }] },
  { id: 'helios', term: 'Helios', definition: 'AMD rack-scale system: 18 trays × 4 MI455X = 72 GPUs on a UALink-over-Ethernet scale-up fabric.' },
  { id: 'oidc', term: 'OIDC', definition: 'OpenID Connect: token-based login. Kubernetes can trust OIDC tokens from an identity provider so each actor has its own identity.', links: [{ label: 'Kubernetes docs', href: 'https://kubernetes.io/docs/reference/access-authn-authz/authentication/#openid-connect-tokens' }] },
  { id: 'rbac', term: 'RBAC', definition: 'Kubernetes role-based access control: Roles grant verbs on resources; RoleBindings give them to users or service accounts.', links: [{ label: 'Kubernetes docs', href: 'https://kubernetes.io/docs/reference/access-authn-authz/rbac/' }] },
  { id: 'pdb', term: 'PDB', aliases: ['PodDisruptionBudget'], definition: 'PodDisruptionBudget: limits how many Pods of an app voluntary actions (drain) may take down at once.', links: [{ label: 'Kubernetes docs', href: 'https://kubernetes.io/docs/concepts/workloads/pods/disruptions/' }] },
  { id: 'kernel-gpu', term: 'GPU kernel', aliases: ['kernels'], definition: 'A function launched on the GPU as thousands of parallel threads (not the Linux kernel).', links: [{ label: 'Learn: threads & wavefronts', href: '/learn/gpu-execution-model/' }] },
  { id: 'warp', term: 'warp', definition: 'NVIDIA: 32 threads that execute the same instruction together on one SM.' },
  { id: 'wavefront', term: 'wavefront', definition: 'AMD: 64 threads (work-items) that execute the same instruction together on one CU.' },
  { id: 'lds', term: 'LDS', aliases: ['shared memory'], definition: 'Local Data Share (AMD) / shared memory (NVIDIA): fast on-chip memory shared by one thread block, used to reuse tiles.' },
  { id: 'occupancy', term: 'occupancy', definition: 'How many warps/wavefronts are resident on a CU/SM, limited by registers and LDS; more hides memory latency.' },
  { id: 'ptx', term: 'PTX', definition: 'NVIDIA Parallel Thread Execution: a virtual GPU instruction set; the driver or ptxas compiles it to SASS.', links: [{ label: 'CUDA docs (PTX ISA)', href: 'https://docs.nvidia.com/cuda/' }, { label: 'Learn page', href: '/learn/gpu-isa-ptx/' }] },
  { id: 'sass', term: 'SASS', definition: 'NVIDIA machine code for one GPU architecture (sm_90, sm_100…), produced from PTX.' },
  { id: 'amdgcn', term: 'AMDGCN', aliases: ['gfx950', 'gfx942'], definition: 'AMD GPU machine instruction set, compiled per chip target: gfx942 (MI300X), gfx950 (MI355X).', links: [{ label: 'ROCm docs', href: 'https://rocm.docs.amd.com/en/latest/' }] },
  { id: 'mfma', term: 'MFMA', definition: 'Matrix Fused Multiply-Add: AMD matrix-core instructions (v_mfma_*) that multiply small tiles in one step; NVIDIA’s are mma / wgmma.' },
  { id: 'tensor-core', term: 'Tensor Core', aliases: ['matrix core', 'Matrix core'], definition: 'Matrix engine inside an SM (NVIDIA) or CU (AMD “matrix core”) that does small matrix multiplies per instruction.' },
  { id: 'gemm', term: 'GEMM', aliases: ['GEMMs'], definition: 'General matrix-matrix multiply: the core operation of prefill. GEMV (matrix × vector) dominates decode.' },
  { id: 'roofline', term: 'roofline', definition: 'Performance model: a kernel is memory-bound below a FLOPs-per-byte ridge and compute-bound above it.', links: [{ label: 'Wikipedia', href: 'https://en.wikipedia.org/wiki/Roofline_model' }, { label: 'Learn page', href: '/learn/gpu-memory-hierarchy/' }] },
  { id: 'arithmetic-intensity', term: 'arithmetic intensity', definition: 'FLOPs done per byte read from memory. Prefill: thousands; decode at batch 1: about 2.' },
  { id: 'flashattention', term: 'FlashAttention', definition: 'An attention kernel that tiles Q·Kᵀ and softmax in on-chip memory instead of writing the full matrix to HBM.' },
  { id: 'pagedattention', term: 'PagedAttention', aliases: ['paged attention'], definition: 'vLLM’s KV-cache scheme: fixed-size blocks plus a per-sequence block table, like virtual memory pages.', links: [{ label: 'Paper', href: 'https://arxiv.org/abs/2309.06180' }] },
  { id: 'ttft', term: 'TTFT', definition: 'Time to first token: mostly prefill time. Its partner metric is ITL, inter-token latency (decode).' },
  { id: 'moe', term: 'MoE', aliases: ['mixture-of-experts'], definition: 'Mixture of experts: each layer has many expert MLPs and a router picks a few per token; gpt-oss is MoE.' },
  { id: 'token', term: 'token', aliases: ['tokens'], definition: 'A word piece from the model’s vocabulary; LLMs read and write text as token IDs.' },
  { id: 'xcd', term: 'XCD', definition: 'Accelerator complex die: one of the 8 compute chiplets in an AMD MI300/MI350-series GPU. On MI355X each has 36 CUs (32 enabled) and a 4 MB L2. Compute partitions follow XCD lines.', links: [{ label: 'AMD CDNA 4 white paper', href: 'https://www.amd.com/content/dam/amd/en/documents/instinct-tech-docs/white-papers/amd-cdna-4-architecture-whitepaper.pdf' }, { label: 'Learn: What a GPU is', href: '/learn/what-is-a-gpu/' }] },
  { id: 'iod', term: 'IOD', definition: 'I/O die: the base chiplet under the XCDs in AMD Instinct GPUs. It holds the Infinity Cache, HBM controllers, Infinity Fabric links and PCIe. MI355X has two; NPS2 memory partitions follow IOD lines.', links: [{ label: 'AMD CDNA 4 white paper', href: 'https://www.amd.com/content/dam/amd/en/documents/instinct-tech-docs/white-papers/amd-cdna-4-architecture-whitepaper.pdf' }] },
  { id: 'xcp', term: 'XCP', definition: 'Accelerated compute processor: the logical GPU produced by an AMD compute partition. SPX gives one XCP per card, CPX gives eight. Each XCP is enumerated as its own GPU by amd-smi and HIP.', links: [{ label: 'AMD SMI partitioning', href: 'https://rocm.docs.amd.com/projects/amdsmi/en/latest/conceptual/partition.html' }, { label: 'Learn: Partitioning', href: '/learn/gpu-partitioning/' }] },
  { id: 'psp', term: 'PSP', definition: 'Platform Security Processor: the on-GPU security processor on AMD GPUs. It boots from board firmware, verifies and loads microcode for the other blocks, and runs trusted apps such as RAS and XGMI handling.', links: [{ label: 'amdgpu driver core', href: 'https://docs.kernel.org/gpu/amdgpu/driver-core.html' }, { label: 'Learn: Boot and firmware', href: '/learn/gpu-boot-and-firmware/' }] },
  { id: 'smu', term: 'SMU', definition: 'System Management Unit: the power-management microcontroller on AMD GPUs. It controls clocks, power limits and thermal throttling.', links: [{ label: 'amdgpu driver core', href: 'https://docs.kernel.org/gpu/amdgpu/driver-core.html' }] },
  { id: 'gsp', term: 'GSP', definition: 'GPU System Processor: an on-GPU processor on NVIDIA GPUs that runs firmware shipped with the driver and takes over initialization and management work. The open kernel modules require GSP firmware from the same driver release.', links: [{ label: 'NVIDIA GSP firmware', href: 'https://download.nvidia.com/XFree86/Linux-x86_64/580.95.05/README/gsp.html' }, { label: 'Learn: Boot and firmware', href: '/learn/gpu-boot-and-firmware/' }] },
  { id: 'ifwi', term: 'IFWI', definition: 'Integrated Firmware Image: the firmware on an AMD Instinct GPU\'s flash that the PSP boots from, shipped inside a PLDM bundle and flashed through the server BMC.', links: [{ label: 'ROCm compatibility matrix', href: 'https://rocm.docs.amd.com/en/latest/compatibility/compatibility-matrix.html' }, { label: 'Learn: Boot and firmware', href: '/learn/gpu-boot-and-firmware/' }] },
  { id: 'pldm-bundle', term: 'PLDM bundle', definition: 'The firmware package AMD publishes for Instinct GPUs (IFWI and related images), versioned like 01.00.00.00 and listed per ROCm release in the compatibility matrix.', links: [{ label: 'ROCm compatibility matrix', href: 'https://rocm.docs.amd.com/en/latest/compatibility/compatibility-matrix.html' }] },
  { id: 'mxfp4', term: 'MXFP4', definition: 'OCP microscaling 4-bit format: E2M1 values in blocks of 32 sharing one 8-bit power-of-two (E8M0) scale, about 4.25 bits per value. MXFP6 and MXFP8 use the same scheme. Native on AMD CDNA 4.', links: [{ label: 'MX paper', href: 'https://arxiv.org/abs/2310.10537' }, { label: 'Learn: Number formats', href: '/learn/gpu-number-formats/' }] },
  { id: 'nvfp4', term: 'NVFP4', definition: 'NVIDIA\'s 4-bit float format for Blackwell: E2M1 values with an FP8 (E4M3) scale per 16 values plus an FP32 scale per tensor, about 4.5 bits per value.', links: [{ label: 'Inside Blackwell Ultra', href: 'https://developer.nvidia.com/blog/inside-nvidia-blackwell-ultra-the-chip-powering-the-ai-factory-era/' }, { label: 'Learn: Number formats', href: '/learn/gpu-number-formats/' }] },
  { id: 'fp8', term: 'FP8', definition: '8-bit floating point, in two OCP variants: E4M3 (max 448, used for inference) and E5M2 (max 57344, used for gradients). Doubles matrix throughput and halves memory versus BF16.', links: [{ label: 'Learn: Number formats', href: '/learn/gpu-number-formats/' }] },
  { id: 'bf16', term: 'BF16', definition: 'Bfloat16: a 16-bit float with FP32\'s 8-bit exponent and a 7-bit mantissa. The usual format for training and for many served weights.', links: [{ label: 'Learn: Number formats', href: '/learn/gpu-number-formats/' }] },
  { id: 'gpudirect-rdma', term: 'GPUDirect RDMA', definition: 'NVIDIA\'s name for a NIC reading and writing GPU memory directly over PCIe, without staging in host RAM. Needs the GPU and NIC under one root complex and a peer-memory path (nvidia-peermem or dma-buf).', links: [{ label: 'GPUDirect RDMA', href: 'https://docs.nvidia.com/cuda/gpudirect-rdma/index.html' }, { label: 'Learn: Memory and interconnects', href: '/learn/gpu-memory-and-interconnects/' }] },
  { id: 'nvlsm', term: 'NVLSM', definition: 'NVLink Subnet Manager: the service that programs NVSwitch routing tables on Blackwell HGX systems, working alongside Fabric Manager.', links: [{ label: 'Fabric Manager guide', href: 'https://docs.nvidia.com/datacenter/tesla/fabric-manager-user-guide/' }] },
  { id: 'numa', term: 'NUMA', definition: 'Non-uniform memory access: a server\'s CPUs and RAM are split into nodes, and memory or PCIe devices on a far node are slower to reach.', links: [{ label: 'Learn: Node topology', href: '/learn/gpu-node-topology/' }] },
  { id: 'bar', term: 'BAR', definition: 'Base address register: the PCIe address window through which the CPU and other devices reach a device\'s memory. MI355X exposes a 512 GiB BAR, so all of HBM is reachable for GPUDirect-style RDMA.', links: [{ label: 'Learn: Memory and interconnects', href: '/learn/gpu-memory-and-interconnects/' }] },
  { id: 'oam', term: 'OAM', definition: 'OCP Accelerator Module: the mezzanine form factor of MI355X and other datacenter GPUs; eight sit on one universal baseboard (UBB).', links: [{ label: 'AMD CDNA 4 white paper', href: 'https://www.amd.com/content/dam/amd/en/documents/instinct-tech-docs/white-papers/amd-cdna-4-architecture-whitepaper.pdf' }] },
  { id: 'cuda-forward-compatibility', term: 'CUDA forward compatibility', definition: 'Running an application built with a newer CUDA major release on an older data-center driver, by adding the cuda-compat-<major>-<minor> package (a newer libcuda) to LD_LIBRARY_PATH.', links: [{ label: 'Forward compatibility', href: 'https://docs.nvidia.com/deploy/cuda-compatibility/forward-compatibility.html' }, { label: 'Learn: Software stack', href: '/learn/gpu-software-stack/' }] },
  { id: 'tokenizer', term: 'tokenizer', definition: 'Splits text into tokens from a fixed vocabulary and maps each to an integer id. gpt-oss uses o200k_harmony, a byte-pair encoding (BPE) with 201,088 entries.', links: [{ label: 'HF tokenizer summary', href: 'https://huggingface.co/docs/transformers/main/en/tokenizer_summary' }, { label: 'Learn: Tokens and transformers', href: '/learn/tokens-and-transformers/' }] },
  { id: 'bpe', term: 'BPE', definition: 'Byte-pair encoding: a tokenizer built by repeatedly merging the most frequent adjacent byte pairs in training text, so common words become one token and rare ones several.', links: [{ label: 'tiktoken', href: 'https://github.com/openai/tiktoken' }, { label: 'Learn: Tokens and transformers', href: '/learn/tokens-and-transformers/' }] },
  { id: 'embedding', term: 'embedding', definition: 'The lookup that turns a token id into a vector of hidden-size numbers (2,880 for gpt-oss-120b); also the table holding those vectors.', links: [{ label: 'Learn: Tokens and transformers', href: '/learn/tokens-and-transformers/' }] },
  { id: 'hidden-size', term: 'hidden size', definition: 'Width of each token\'s vector inside the model (2,880 for gpt-oss-120b, 8,192 for Llama 3.3 70B).', links: [{ label: 'gpt-oss config', href: 'https://huggingface.co/openai/gpt-oss-120b/blob/main/config.json' }] },
  { id: 'residual-stream', term: 'residual stream', definition: 'The per-token vectors that flow through all layers; each attention or MLP block adds its output to it instead of replacing it.', links: [{ label: 'Learn: Tokens and transformers', href: '/learn/tokens-and-transformers/' }] },
  { id: 'forward-pass', term: 'forward pass', definition: 'One run of the model over a set of input tokens, producing hidden states (and next-token logits) at every position. Prefill is one forward pass; each decode step is another.', links: [{ label: 'Learn: Tokens and transformers', href: '/learn/tokens-and-transformers/' }] },
  { id: 'attention', term: 'attention', definition: 'The layer step where each token mixes in information from earlier tokens: its query is compared with their keys, and their values are averaged with the resulting softmax weights.', links: [{ label: 'Attention Is All You Need', href: 'https://arxiv.org/abs/1706.03762' }, { label: 'Learn: Attention and the KV cache', href: '/learn/attention-and-kv-cache/' }] },
  { id: 'qkv', term: 'QKV', definition: 'Query, key and value: three vectors each token computes per attention head. Queries are compared with keys to weight values. Keys and values are what the KV cache stores.', links: [{ label: 'Learn: Attention and the KV cache', href: '/learn/attention-and-kv-cache/' }] },
  { id: 'gqa', term: 'GQA', definition: 'Grouped-query attention: several query heads share one key/value head (gpt-oss-120b: 64 query, 8 KV heads), cutting KV cache size by the group factor.', links: [{ label: 'GQA paper', href: 'https://arxiv.org/abs/2305.13245' }, { label: 'Learn: Attention and the KV cache', href: '/learn/attention-and-kv-cache/' }] },
  { id: 'rope', term: 'RoPE', definition: 'Rotary position embedding: rotates query and key vectors by position-dependent angles so their dot product depends on the distance between tokens.', links: [{ label: 'RoFormer', href: 'https://arxiv.org/abs/2104.09864' }] },
  { id: 'rmsnorm', term: 'RMSNorm', definition: 'Normalization that rescales a token\'s vector to unit root-mean-square, then applies a learned gain; applied before each attention and MLP block in gpt-oss.', links: [{ label: 'gpt-oss model card', href: 'https://arxiv.org/abs/2508.10925' }] },
  { id: 'swiglu', term: 'SwiGLU', definition: 'MLP form down(silu(gate(x)) * up(x)) used by gpt-oss and Llama experts and MLPs.', links: [{ label: 'gpt-oss model card', href: 'https://arxiv.org/abs/2508.10925' }] },
  { id: 'sliding-window-attention', term: 'sliding-window attention', definition: 'Attention limited to the most recent N tokens (128 in half of gpt-oss\'s layers); those layers need KV for only N tokens per sequence.', links: [{ label: 'vLLM hybrid KV cache', href: 'https://docs.vllm.ai/en/latest/design/hybrid_kv_cache_manager.html' }, { label: 'Learn: Attention and the KV cache', href: '/learn/attention-and-kv-cache/' }] },
  { id: 'router', term: 'router', definition: 'In an MoE layer, the small matrix that scores all experts for a token and selects the top few (top-4 of 128 in gpt-oss-120b).', links: [{ label: 'Learn: Mixture of experts', href: '/learn/mixture-of-experts/' }] },
  { id: 'active-parameters', term: 'active parameters', definition: 'The parameters used to compute one token. For MoE models far fewer than total: gpt-oss-120b has 116.8 B total, 5.1 B active.', links: [{ label: 'gpt-oss model card', href: 'https://arxiv.org/abs/2508.10925' }, { label: 'Learn: Mixture of experts', href: '/learn/mixture-of-experts/' }] },
  { id: 'expert-parallelism', term: 'expert parallelism', definition: 'Spreading an MoE model\'s experts over several GPUs; each MoE layer then needs all-to-all exchanges of token vectors.', links: [{ label: 'vLLM expert parallel', href: 'https://docs.vllm.ai/en/latest/serving/expert_parallel_deployment.html' }] },
  { id: 'logit', term: 'logit', definition: 'The raw score a model outputs for one vocabulary entry; a softmax over all logits gives next-token probabilities.', links: [{ label: 'Learn: Tokens and transformers', href: '/learn/tokens-and-transformers/' }] },
  { id: 'itl', term: 'ITL', definition: 'Inter-token latency: time between two consecutive output tokens of one request, about one decode step. Also called time per output token (TPOT).', links: [{ label: 'vLLM metrics', href: 'https://docs.vllm.ai/en/latest/usage/metrics.html' }, { label: 'Learn: Decode', href: '/learn/decode-phase/' }] },
  { id: 'chunked-prefill', term: 'chunked prefill', definition: 'Splitting a long prompt\'s prefill across several engine steps, each capped by a token budget (for example 8,192 tokens).', links: [{ label: 'Sarathi-Serve', href: 'https://arxiv.org/abs/2403.02310' }, { label: 'Learn: Prefill', href: '/learn/prefill-phase/' }] },
  { id: 'prefix-caching', term: 'prefix caching', definition: 'Reusing KV blocks of a prompt start that an earlier request already computed, matched by a chained hash of full blocks.', links: [{ label: 'vLLM prefix caching', href: 'https://docs.vllm.ai/en/latest/design/prefix_caching.html' }, { label: 'Learn: KV cache management', href: '/learn/kv-cache-management/' }] },
  { id: 'block-table', term: 'block table', definition: 'Per-sequence map from logical KV blocks to physical blocks in GPU memory, like a page table; the core of PagedAttention.', links: [{ label: 'PagedAttention paper', href: 'https://arxiv.org/abs/2309.06180' }, { label: 'Learn: KV cache management', href: '/learn/kv-cache-management/' }] },
  { id: 'continuous-batching', term: 'continuous batching', definition: 'Re-forming the batch at every decode step so finished requests leave and new ones join immediately; also called iteration-level scheduling.', links: [{ label: 'Learn: Batching and scheduling', href: '/learn/batching-and-scheduling/' }] },
  { id: 'preemption', term: 'preemption', definition: 'Evicting a running request\'s KV cache when memory runs out, to recompute or reload it later; counted by vllm:num_preemptions.', links: [{ label: 'vLLM optimization', href: 'https://docs.vllm.ai/en/latest/configuration/optimization.html' }] },
  { id: 'head-of-line-blocking', term: 'head-of-line blocking', definition: 'Short requests waiting behind a long one that occupies the step budget.', links: [{ label: 'Learn: Prefill', href: '/learn/prefill-phase/' }] },
  { id: 'mfu', term: 'MFU', definition: 'Model FLOPs utilization: the share of a chip\'s peak FLOP/s that a workload actually achieves.', links: [{ label: 'Learn: Prefill', href: '/learn/prefill-phase/' }] },
  { id: 'ridge-point', term: 'ridge point', definition: 'Peak FLOP/s divided by memory bandwidth: the arithmetic intensity above which a kernel is compute-bound. About 625 FLOP/byte for MI355X at FP8.', links: [{ label: 'Roofline model', href: 'https://en.wikipedia.org/wiki/Roofline_model' }, { label: 'Learn: Memory hierarchy and roofline', href: '/learn/gpu-memory-hierarchy/' }] },
  { id: 'draft-model', term: 'draft model', definition: 'In speculative decoding, the small fast model that proposes several tokens for the target model to verify.', links: [{ label: 'Leviathan et al.', href: 'https://arxiv.org/abs/2211.17192' }, { label: 'Learn: Speculative decoding', href: '/learn/speculative-decoding/' }] },
  { id: 'acceptance-rate', term: 'acceptance rate', definition: 'In speculative decoding, the chance the target model keeps a draft token. Expected tokens per round = (1 − α^(k+1)) / (1 − α).', links: [{ label: 'Leviathan et al.', href: 'https://arxiv.org/abs/2211.17192' }, { label: 'Learn: Speculative decoding', href: '/learn/speculative-decoding/' }] },
  { id: 'eagle', term: 'EAGLE', definition: 'A speculative decoding method whose light draft head runs on the target model\'s hidden states and proposes a tree of tokens verified in one pass.', links: [{ label: 'EAGLE paper', href: 'https://arxiv.org/abs/2401.15077' }, { label: 'EAGLE-3', href: 'https://arxiv.org/abs/2503.01840' }] },
  { id: 'kubelet-plugin', term: 'kubelet plugin', definition: 'A node-local gRPC server a DRA driver runs next to the kubelet. It registers through /var/lib/kubelet/plugins_registry and answers NodePrepareResources and NodeUnprepareResources.', links: [{ label: 'DRA on the node', href: '/learn/dra-on-the-node/' }, { label: 'Kubernetes: how DRA works', href: 'https://kubernetes.io/docs/concepts/resource-management/dynamic-resource-allocation/how-dra-works/' }] },
  { id: 'nodeprepareresources', term: 'NodePrepareResources', definition: 'DRA gRPC call from the kubelet to a driver before a Pod\'s containers start. The driver sets up the claim\'s devices and returns CDI device IDs. Its pair, NodeUnprepareResources, runs after the last Pod using the claim stops.', links: [{ label: 'DRA on the node', href: '/learn/dra-on-the-node/' }] },
  { id: 'cel', term: 'CEL', definition: 'Common Expression Language. DeviceClasses and ResourceClaims use CEL expressions over device.driver, device.attributes and device.capacity to select devices. An unknown attribute is an error, not false.', links: [{ label: 'DRA objects', href: '/learn/dra-objects/' }, { label: 'cel.dev', href: 'https://cel.dev/' }] },
  { id: 'resourceclaim-controller', term: 'resourceclaim controller', definition: 'Controller in kube-controller-manager that creates one ResourceClaim per Pod from a ResourceClaimTemplate, owns it by the Pod, and deletes it when the Pod is gone.', links: [{ label: 'DRA objects', href: '/learn/dra-objects/' }] },
  { id: 'devicetaintrule', term: 'DeviceTaintRule', definition: 'Cluster-scoped DRA object that taints selected devices (NoSchedule, NoExecute or None) without the driver. Alpha and off by default in Kubernetes 1.35 (resource.k8s.io/v1alpha3).', links: [{ label: 'DRA objects', href: '/learn/dra-objects/#newer-features-and-their-status' }, { label: 'Kubernetes: device taints', href: 'https://kubernetes.io/docs/concepts/resource-management/dynamic-resource-allocation/device-taints/' }] },
  { id: 'admin-access', term: 'admin access', definition: 'DRA request flag (adminAccess: true) that allocates devices even if other claims use them, for monitoring. Only allowed in namespaces labelled resource.kubernetes.io/admin-access=true. Beta, on in 1.35.', links: [{ label: 'DRA objects', href: '/learn/dra-objects/#admin-access' }] },
  { id: 'prioritized-list', term: 'prioritized list', definition: 'DRA request form (firstAvailable) that lists alternatives in order; the scheduler takes the first one it can satisfy. Beta, on in Kubernetes 1.35.', links: [{ label: 'DRA objects', href: '/learn/dra-objects/' }] },
  { id: 'podresources-api', term: 'PodResources API', definition: 'Local kubelet gRPC API (List, Get, GetAllocatableResources) that tells node agents which devices each container got, including DRA devices. Used by GPU metrics exporters to map GPUs to Pods.', links: [{ label: 'GPU allocation in k8s', href: '/learn/k8s-gpu-allocation/' }] },
  { id: 'render-node', term: 'render node', definition: 'Per-GPU DRM device file /dev/dri/renderD<N> (minor 128 and up). ROCm can use a GPU only if the process may open its render node, so passing one render node plus /dev/kfd limits a container to that GPU.', links: [{ label: 'CDI', href: '/learn/cdi-device-injection/' }] },
  { id: 'gpucluster', term: 'GPUCluster', definition: 'NVIDIA GPU Operator custom resource (singleton gpu-cluster) that manages the NVIDIA DRA driver, ComputeDomains, DCGM Exporter and a DRA validator. A cluster has a GPUCluster or a ClusterPolicy, not both.', links: [{ label: 'GPU operators', href: '/learn/gpu-operators/' }, { label: 'NVIDIA docs', href: 'https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/dra-intro-install.html' }] },
  { id: 'computedomain', term: 'ComputeDomain', definition: 'NVIDIA DRA driver object that forms an IMEX domain around a workload\'s Pods so GPUs in different NVL72 trays can share memory over NVLink. Lives as long as the workload.', links: [{ label: 'GPU operators', href: '/learn/gpu-operators/#computedomains' }, { label: 'NVIDIA docs', href: 'https://docs.nvidia.com/datacenter/cloud-native/gpu-operator/latest/dra-cds.html' }] },
  { id: 'whereabouts', term: 'whereabouts', definition: 'Cluster-wide IPAM CNI plugin that stores IP allocations in Kubernetes CRDs (IPPool). A reconciler frees leaked addresses.', links: [{ label: 'GPU Pod networking', href: '/learn/gpu-pod-networking/' }, { label: 'whereabouts', href: 'https://github.com/k8snetworkplumbingwg/whereabouts' }] },
  { id: 'macvlan', term: 'macvlan', definition: 'CNI plugin that creates a child interface with its own MAC on a host NIC and moves it into the Pod.', links: [{ label: 'GPU Pod networking', href: '/learn/gpu-pod-networking/' }, { label: 'macvlan plugin', href: 'https://www.cni.dev/plugins/current/main/macvlan/' }] },
  { id: 'nicclusterpolicy', term: 'NicClusterPolicy', definition: 'NVIDIA Network Operator custom resource (name nic-cluster-policy) that deploys OFED driver, RDMA or SR-IOV device plugins, Multus, IPAM and NIC configuration on ConnectX nodes.', links: [{ label: 'GPU Pod networking', href: '/learn/gpu-pod-networking/#nvidia-network-operator-for-comparison' }, { label: 'Network Operator', href: 'https://github.com/Mellanox/network-operator' }] },
  { id: 'node-labeller', term: 'node labeller', definition: 'AMD GPU operator operand that writes amd.com/gpu.* and beta.amd.com/gpu.* inventory labels on GPU nodes. Independent of allocation; runs with the device plugin off.', links: [{ label: 'GPU operators', href: '/learn/gpu-operators/' }] },
  { id: 'poison', term: 'Poison', aliases: ['deferred error'], definition: 'An uncorrectable error that nobody has read yet. The data is marked poisoned and the system acts only if something consumes it.', links: [{ label: 'AMD RAS and ECC', href: '/learn/amd-ras-and-ecc/' }] },
  { id: 'bad-page-retirement', term: 'Bad page retirement', definition: 'The AMD driver stops using an HBM page after an uncorrectable error and records it in board EEPROM. MI35x flags the GPU after 128 retired pages.', links: [{ label: 'AMD RAS and ECC', href: '/learn/amd-ras-and-ecc/' }, { label: 'AMD tools', href: '/learn/amd-gpu-tools/' }] },
  { id: 'cper', term: 'CPER', definition: 'Common Platform Error Record: a UEFI-standard error report the driver builds from hardware error registers; read with amd-smi ras --cper. Fatal ATHUB events write none.', links: [{ label: 'AMD RAS and ECC', href: '/learn/amd-ras-and-ecc/' }] },
  { id: 'aca-bank', term: 'ACA bank', definition: 'AMD\'s machine-check error registers (status, address, IP id, syndrome), held by the SMU. The only data that says which on-chip block failed.', links: [{ label: 'AMD RAS and ECC', href: '/learn/amd-ras-and-ecc/' }] },
  { id: 'afid', term: 'AFID', definition: 'AMD Field ID: a code derived from a CPER record (amd-smi ras --afid) that AMD support uses to match a field failure to a known cause.', links: [{ label: 'AMD RAS and ECC', href: '/learn/amd-ras-and-ecc/' }, { label: 'AFID event list', href: 'https://docs.amd.com/r/en-US/AMD_Field_ID_70122_v1.0/AFID-Event-List' }] },
  { id: 'umc', term: 'UMC', definition: 'Unified Memory Controller: the AMD GPU block that drives the HBM stacks and owns HBM ECC.', links: [{ label: 'AMD RAS and ECC', href: '/learn/amd-ras-and-ecc/' }] },
  { id: 'athub', term: 'ATHUB', definition: 'Address Translation hub on AMD GPUs. On MI300/MI350 its name labels the fatal-error signal path, which is not proof that ATHUB itself failed.', links: [{ label: 'AMD RAS and ECC', href: '/learn/amd-ras-and-ecc/' }, { label: 'GPU failures', href: '/learn/gpu-failures/' }] },
  { id: 'xgmi-hive', term: 'XGMI hive', definition: 'The set of AMD GPUs joined by one coherent XGMI (Infinity Fabric) network; all 8 GPUs of an MI355X node. A fatal reset covers the whole hive.', links: [{ label: 'AMD tools', href: '/learn/amd-gpu-tools/' }, { label: 'GPU failures', href: '/learn/gpu-failures/' }] },
  { id: 'mode1-reset', term: 'MODE1 reset', definition: 'The heaviest in-band AMD GPU reset: all blocks reset, VRAM lost, PSP reloads all firmware, power stays on. On MI35x it resets the whole hive.', links: [{ label: 'AMD RAS and ECC', href: '/learn/amd-ras-and-ecc/' }] },
  { id: 'oam-id', term: 'OAM ID', definition: 'The physical slot of an AMD GPU module on the baseboard, shown by amd-smi list -e. It differs from the GPU index; use it with DC Ops.', links: [{ label: 'GPU process ↔ Pod', href: '/learn/gpu-process-to-pod/' }] },
  { id: 'freshness-canary', term: 'Freshness canary', definition: 'An alert that fires when a counter that must always advance (gpu_energy_consumed) stops changing while the scrape still succeeds: the exporter data is stale.', links: [{ label: 'GPU metrics', href: '/learn/gpu-metrics/' }] },
  { id: 'cold-power-cycle', term: 'Cold power cycle', definition: 'Removing power from the server (BMC off, confirm Off, on) so the GPU baseboard and its firmware restart. A BMC "cycle" (ForceRestart) does not remove power.' },
  { id: 'compute-tray', term: 'compute tray', definition: 'A 1U sled in a rack-scale system with CPUs, 4 GPUs, NICs and its own BMC; one Linux host and expected to be one Kubernetes node.', links: [{ label: 'Rack-scale GPUs', href: '/learn/rack-scale-gpus/' }] },
  { id: 'switch-tray', term: 'switch tray', definition: 'A rack sled holding scale-up switch chips (NVSwitch on NVL72, Tomahawk 6 on Helios) with its own management CPU and BMC; runs no workloads.', links: [{ label: 'Rack-scale GPUs', href: '/learn/rack-scale-gpus/' }] },
  { id: 'nvlink-domain', term: 'NVLink domain', definition: 'The set of GPUs that reach each other directly over NVLink: 8 on an HGX baseboard, 72 in a GB300 NVL72 rack.', links: [{ label: 'Rack-scale GPUs', href: '/learn/rack-scale-gpus/' }, { label: 'NVLink', href: 'https://www.nvidia.com/en-us/data-center/nvlink/' }] },
  { id: 'ualink', term: 'UALink', definition: 'Ultra Accelerator Link: open accelerator-to-accelerator interconnect standard (current spec: UALink 200G 1.0). Helios carries it over Ethernet (UALoE) through Tomahawk 6 switch trays.', links: [{ label: 'UALink Consortium', href: 'https://ualinkconsortium.org/' }] },
  { id: 'ualoe', term: 'UALoE', definition: 'UALink over Ethernet: AMD Helios\' scale-up fabric, single switch hop through 6 in-rack Tomahawk 6 switch trays.', links: [{ label: 'AMD Helios brief', href: 'https://www.amd.com/content/dam/amd/en/documents/products/accelerators/instinct/amd-instinct-helios-blueprint-brochure.pdf' }] },
  { id: 'tomahawk-6', term: 'Tomahawk 6', definition: 'Broadcom Ethernet switch chip, 102.4 Tb/s with 512 lanes of 200G SerDes. Helios uses 2 per switch tray, 12 per rack.', links: [{ label: 'Broadcom', href: 'https://investors.broadcom.com/news-releases/news-release-details/broadcom-ships-tomahawk-6-worlds-first-1024-tbps-switch' }] },
  { id: 'resourceslice-wipe', term: 'ResourceSlice wipe', definition: 'When a DRA plugin stays disconnected longer than the kubelet\'s 30 s wiping delay (Kubernetes 1.35), the kubelet deletes that node\'s ResourceSlices for the driver.' },
  { id: 'exec-mask', term: 'EXEC mask', definition: 'AMD\'s 64-bit per-wavefront register with one bit per lane; vector instructions only write results for lanes whose bit is 1. How branches and divergence are implemented on CDNA.', links: [{ label: 'CDNA4 ISA', href: 'https://www.amd.com/content/dam/amd/en/documents/instinct-tech-docs/instruction-set-architectures/amd-instinct-cdna4-instruction-set-architecture.pdf' }, { label: 'Page', href: '/learn/gpu-execution-model/' }] },
  { id: 'vgpr', term: 'VGPR', definition: 'Vector general-purpose register on AMD GPUs: one 32-bit value per lane of a wavefront. On MI355X a wave can use up to 512 (256 architectural + 256 accumulation); fewer per wave means more waves fit (occupancy).', links: [{ label: 'ROCm specs', href: 'https://rocm.docs.amd.com/en/latest/reference/gpu-arch-specs.html' }, { label: 'Page', href: '/learn/gpu-execution-model/' }] },
  { id: 'sgpr', term: 'SGPR', definition: 'Scalar general-purpose register on AMD GPUs: one value shared by the whole wavefront, used for kernel arguments, pointers and loop counters. Run by the scalar unit (s_* instructions).', links: [{ label: 'LLVM AMDGPU', href: 'https://llvm.org/docs/AMDGPUUsage.html' }, { label: 'Page', href: '/learn/gpu-execution-model/' }] },
  { id: 'agpr', term: 'AGPR', definition: 'Accumulation VGPR (AccVGPR) on AMD CDNA: a second register bank that usually holds MFMA accumulators, written as a[...] in assembly.', links: [{ label: 'CDNA4 ISA', href: 'https://www.amd.com/content/dam/amd/en/documents/instinct-tech-docs/instruction-set-architectures/amd-instinct-cdna4-instruction-set-architecture.pdf' }, { label: 'Page', href: '/learn/gpu-isa-ptx/' }] },
  { id: 'divergence', term: 'Divergence', definition: 'When threads of one warp/wavefront take different branches; the hardware runs each path with some lanes masked off, so the group pays for both.', links: [{ label: 'Page', href: '/learn/gpu-execution-model/#divergence' }] },
  { id: 'simt', term: 'SIMT', definition: 'Single Instruction, Multiple Threads: code is written per thread, but hardware fetches one instruction for a whole warp (32) or wavefront (64).', links: [{ label: 'Page', href: '/learn/gpu-execution-model/' }] },
  { id: 'code-object', term: 'Code object', definition: 'An AMDGPU ELF file holding compiled kernels for one gfx target, plus metadata (registers, LDS, wavefront size). Several are packed in a .hip_fatbin offload bundle.', links: [{ label: 'LLVM AMDGPU', href: 'https://llvm.org/docs/AMDGPUUsage.html' }, { label: 'Page', href: '/learn/gpu-isa-ptx/' }] },
  { id: 'fatbinary', term: 'Fatbinary', definition: 'Container embedded in a host ELF with device code for several GPU architectures: .nv_fatbin (cubins + PTX) on NVIDIA, .hip_fatbin (offload bundle) on AMD.', links: [{ label: 'nvcc', href: 'https://docs.nvidia.com/cuda/cuda-compiler-driver-nvcc/index.html' }, { label: 'Bundler', href: 'https://clang.llvm.org/docs/ClangOffloadBundler.html' }, { label: 'Page', href: '/learn/gpu-isa-ptx/' }] },
  { id: 'wgmma', term: 'wgmma', definition: 'Hopper (sm_90a) PTX instruction: an asynchronous matrix multiply issued by a warpgroup of 128 threads, with operands in shared memory.', links: [{ label: 'PTX ISA', href: 'https://docs.nvidia.com/cuda/parallel-thread-execution/index.html' }, { label: 'Page', href: '/learn/gpu-isa-ptx/' }] },
  { id: 'tcgen05', term: 'tcgen05', definition: 'Blackwell (sm_100a) PTX instruction family for 5th-generation Tensor Cores; tcgen05.mma accumulates into per-SM Tensor Memory.', links: [{ label: 'PTX ISA', href: 'https://docs.nvidia.com/cuda/parallel-thread-execution/index.html' }, { label: 'Page', href: '/learn/gpu-isa-ptx/' }] },
  { id: 'tma', term: 'TMA', definition: 'Tensor Memory Accelerator: Hopper+ copy engine that moves 1D-5D tiles between global and shared memory from one thread\'s request (cp.async.bulk.tensor).', links: [{ label: 'Hopper tuning', href: 'https://docs.nvidia.com/cuda/hopper-tuning-guide/index.html' }, { label: 'Page', href: '/learn/gpu-isa-ptx/' }] },
  { id: 'infinity-cache', term: 'Infinity Cache', definition: 'AMD\'s last-level cache shared by all XCDs of an MI300/MI355-class GPU; 256 MB on MI355X; rocminfo reports it as L3.', links: [{ label: 'ROCm specs', href: 'https://rocm.docs.amd.com/en/latest/reference/gpu-arch-specs.html' }, { label: 'Page', href: '/learn/gpu-memory-hierarchy/' }] },
  { id: 'bank-conflict', term: 'Bank conflict', definition: 'Several lanes accessing different addresses in the same LDS/shared-memory bank at once, which serializes the access. CDNA4 LDS has 64 banks of 4 bytes.', links: [{ label: 'Page', href: '/learn/gpu-memory-hierarchy/#lds-bank-conflicts' }] },
  { id: 'split-k', term: 'Split-K', definition: 'Splitting a GEMM\'s K dimension across several workgroups and summing partial results, to use more CUs when M and N are small (decode).', links: [{ label: 'Page', href: '/learn/gemm-tiling/#when-there-are-not-enough-tiles' }] },
  { id: 'grouped-gemm', term: 'Grouped GEMM', definition: 'One kernel launch that runs many differently sized GEMMs, e.g. one per MoE expert, choosing each tile\'s weight matrix from an expert-id table.', links: [{ label: 'vLLM fused_moe', href: 'https://github.com/vllm-project/vllm/blob/main/vllm/model_executor/layers/fused_moe/fused_moe.py' }, { label: 'Page', href: '/learn/gemm-tiling/#grouped-gemm-for-mixture-of-experts' }] },
  { id: 'online-softmax', term: 'Online softmax', definition: 'Computing softmax block by block with a running max and sum, rescaling earlier partial results when the max grows; exact, used by FlashAttention.', links: [{ label: 'Paper', href: 'https://arxiv.org/abs/1805.02867' }, { label: 'Page', href: '/learn/flash-attention/#the-online-softmax' }] },
  { id: 'split-kv', term: 'Split-KV', definition: 'Flash-Decoding: splitting one sequence\'s KV cache across several workgroups in decode attention, then combining partial softmax results.', links: [{ label: 'Flash-Decoding', href: 'https://crfm.stanford.edu/2023/10/12/flashdecoding.html' }, { label: 'Page', href: '/learn/flash-attention/#too-few-workgroups-split-kv' }] },
  { id: 'reshape-and-cache', term: 'reshape_and_cache', definition: 'vLLM kernel that copies each token\'s new K and V rows into its paged KV-cache slot given by slot_mapping; one workgroup per token.', links: [{ label: 'Source', href: 'https://github.com/vllm-project/vllm/blob/main/csrc/cache_kernels.cu' }, { label: 'Page', href: '/learn/llm-kernels/#writing-the-kv-cache-a-real-kernel' }] },
  { id: 'rocprofv3', term: 'rocprofv3', definition: 'AMD\'s command-line profiler (rocprofiler-sdk): kernel traces with names, durations, VGPR/LDS use, and hardware counters.', links: [{ label: 'Docs', href: 'https://rocm.docs.amd.com/projects/rocprofiler-sdk/en/latest/how-to/using-rocprofv3.html' }, { label: 'Page', href: '/learn/llm-kernels/#seeing-real-kernels' }] },
  { id: 'label-selector', term: 'label selector', definition: 'A Kubernetes query over labels (key=value tags); Deployments, Services and many controllers find their objects by selector instead of keeping lists.', links: [{ label: 'Labels and selectors', href: 'https://kubernetes.io/docs/concepts/overview/working-with-objects/labels/' }] },
  { id: 'bdf', term: 'BDF', definition: 'Bus:device.function, the PCI address of a device, with the PCI domain in front (e.g. 0000:11:00.0). The one GPU name every tool (lspci, sysfs, amd-smi, DRA pciBusID) agrees on.', links: [{ label: 'Node topology', href: '/learn/gpu-node-topology/' }] },
  { id: 'pcie-root-complex', term: 'PCIe root complex', definition: 'The CPU\'s PCIe entry point; every device hangs below one. Devices under the same root (and switch) can exchange data without crossing the CPU. Exposed in DRA as resource.kubernetes.io/pcieRoot.', links: [{ label: 'Node topology', href: '/learn/gpu-node-topology/' }] },
  { id: 'e8m0', term: 'E8M0', definition: 'The 8-bit shared scale of the OCP MX formats: an exponent only (bias 127), so the scale is always a power of two. One E8M0 scale serves a block of 32 elements.', links: [{ label: 'Number formats', href: '/learn/gpu-number-formats/#scaling-one-shared-multiplier-per-block' }] },
  { id: 'mantissa', term: 'Mantissa', definition: 'The fraction bits of a floating-point number: where the value lies between one power of two and the next. More mantissa bits mean more precision; E4M3 has 3.', links: [{ label: 'Number formats', href: '/learn/gpu-number-formats/#the-idea-first' }] },
  { id: 'saturation', term: 'Saturation', definition: 'When a value is larger than a format\'s largest number, it is stored as that largest number instead of infinity. Quantizers use it for formats without infinity (E4M3, FP6, FP4).', links: [{ label: 'Number formats', href: '/learn/gpu-number-formats/' }] },
  { id: 'simd-unit', term: 'SIMD unit', definition: 'A group of 16 lanes in an AMD CU that run one instruction together; a 64-thread wavefront passes through it in 4 cycles. Each MI355X CU has 4.', links: [{ label: 'What a GPU is', href: '/learn/what-is-a-gpu/#zoom-in-package-to-lane' }] },
  { id: 'aql-packet', term: 'AQL packet', definition: 'Architected Queuing Language packet (HSA standard): the 64-byte record a ROCm program writes into a GPU queue to launch a kernel. It holds the workgroup and grid sizes, LDS and scratch sizes, and pointers to the code, the arguments and a completion signal.', links: [{ label: 'HSA hsa.h', href: 'https://github.com/ROCm/ROCR-Runtime/blob/amd-staging/runtime/hsa-runtime/inc/hsa.h' }, { label: 'Software stack', href: '/learn/gpu-software-stack/' }] },
  { id: 'doorbell', term: 'Doorbell', definition: 'A memory-mapped GPU register a process writes to tell the command processor "new packets in my queue". One ordinary store, no system call, which is why kernel launches bypass the Linux driver.', links: [{ label: 'Software stack', href: '/learn/gpu-software-stack/' }, { label: 'Boot and firmware', href: '/learn/gpu-boot-and-firmware/' }] },
  { id: 'kernarg-buffer', term: 'Kernarg buffer', definition: 'Kernel-argument buffer: memory the GPU can read that holds a kernel launch\'s arguments (buffer addresses, sizes). The AQL packet carries a pointer to it.', links: [{ label: 'Software stack', href: '/learn/gpu-software-stack/' }] },
  { id: 'dcm', term: 'DCM', definition: 'Device Config Manager: the AMD GPU Operator component that applies a GPU partition profile to a node, after the node is tainted so all GPU work is evicted.', links: [{ label: 'AMD DCM docs', href: 'https://instinct.docs.amd.com/projects/gpu-operator/en/latest/dcm/applying-partition-profiles.html' }, { label: 'Partitioning', href: '/learn/gpu-partitioning/' }] },
  { id: 'operand', term: 'Operand', definition: 'One component an operator deploys and keeps in sync, usually as a DaemonSet per enabled section of its custom resource. AMD GPU Operator operands include the DRA driver, node labeller and metrics exporter.', links: [{ label: 'GPU operators', href: '/learn/gpu-operators/' }] },
  { id: 'maxsurge', term: 'maxSurge', definition: 'DaemonSet/Deployment rolling-update field: how many extra Pods may exist during an update. 0 means delete the old Pod first, then start the new one; the AMD operator uses 0 for the DRA driver.', links: [{ label: 'DaemonSet rolling update', href: 'https://kubernetes.io/docs/tasks/manage-daemon/update-daemon-set/' }, { label: 'GPU operators', href: '/learn/gpu-operators/#worked-example-a-new-dra-driver-image-reaches-10-nodes' }] },
  { id: 'pcie-switch', term: 'PCIe switch', definition: 'A chip that fans one PCIe link from the CPU out to several devices. In many 8-GPU servers each switch carries one GPU and its NIC, so GPU-to-NIC traffic need not reach the CPU.', links: [{ label: 'Learn: Node topology', href: '/learn/gpu-node-topology/' }] },
  { id: 'first-fit', term: 'first fit', definition: 'How the Kubernetes DRA allocator picks a device: it walks pools and ResourceSlices in lexicographic name order, devices in slice order, and takes the first free device that passes all selectors and constraints. No scoring.', links: [{ label: 'DRA objects in detail', href: '/learn/dra-objects/' }, { label: 'Kubernetes docs', href: 'https://kubernetes.io/docs/concepts/resource-management/dynamic-resource-allocation/dra-api/#resourceslice-naming-and-prioritization' }] },
  { id: 'pcieroot', term: 'pcieRoot', definition: 'Standard DRA device attribute resource.kubernetes.io/pcieRoot: the PCIe root complex a device hangs off. Used in matchAttribute constraints to keep devices together.', links: [{ label: 'DRA objects in detail', href: '/learn/dra-objects/' }] },
  { id: 'wedge', term: 'Wedge', definition: 'A GPU state after a failed reset: the devices are still on PCIe but the GPU\'s boot processor (PSP) never came back, so software cannot use them. On MI35x only removing power (a cold power cycle) recovers it.', links: [{ label: 'GPU failures', href: '/learn/gpu-failures/' }] },
  { id: 'row-remapping', term: 'Row remapping', definition: 'NVIDIA\'s graceful HBM wear mechanism: a bad memory row is swapped for a spare. Xid 63 reports a remap, Xid 64 a failed one; read with nvidia-smi -q -d ROW_REMAPPER. AMD\'s counterpart is bad-page retirement.', links: [{ label: 'Xid catalog', href: 'https://docs.nvidia.com/deploy/xid-errors/analyzing-xid-catalog.html' }, { label: 'NVIDIA tools', href: '/learn/nvidia-gpu-tools/' }] },
  { id: 'wiping-delay', term: 'wiping delay', definition: 'The 30 s the kubelet waits after a DRA driver disconnects before deleting that node\'s ResourceSlices for the driver (Kubernetes 1.35 defaultWipingDelay).', links: [{ label: 'kubelet DRA manager', href: 'https://github.com/kubernetes/kubernetes/blob/release-1.35/pkg/kubelet/cm/dra/manager.go' }] },
  { id: 'coalescing', term: 'Coalescing', definition: 'The GPU merging the memory requests of a wave\'s lanes into as few cache lines as possible. Neighbouring lanes reading neighbouring addresses coalesce fully; scattered or strided addresses fetch many lines for few useful bytes.', links: [{ label: 'Memory hierarchy', href: '/learn/gpu-memory-hierarchy/#worked-example-one-wavefronts-load' }] },
  { id: 'double-buffering', term: 'Double buffering', definition: 'Keeping two LDS buffers in a tiled kernel: loads for the next K-step fill one while the matrix cores compute from the other, so math and memory overlap. Also called software pipelining; more buffers = more stages.', links: [{ label: 'GEMM tiling', href: '/learn/gemm-tiling/#double-buffering-software-pipelining' }] },
  { id: 'epilogue', term: 'Epilogue', definition: 'The end of a GEMM kernel: converts FP32 accumulators to the output format and fuses cheap element-wise work (bias, activation, residual add) before storing the tile once.', links: [{ label: 'GEMM tiling', href: '/learn/gemm-tiling/#the-epilogue' }] },
  { id: 'vcc', term: 'VCC', definition: 'Vector condition code: a 64-bit AMD scalar register pair that a vector compare (v_cmp_*) writes, one bit per lane; bits of lanes that are off are 0. Combined with EXEC to branch.', links: [{ label: 'How a GPU runs code', href: '/learn/gpu-execution-model/#divergence-one-wave-through-an-ifelse-step-by-step' }] },
  { id: 'kernel-descriptor', term: 'Kernel descriptor', definition: 'AMD: a 64-byte block (symbol <kernel>.kd) in the code object that tells the command processor how to start a kernel: code address, register counts, LDS and argument sizes.', links: [{ label: 'PTX and AMDGCN', href: '/learn/gpu-isa-ptx/#worked-example-one-kernel-source-to-silicon' }] },
  { id: 'kernarg-segment', term: 'Kernarg segment', definition: 'AMD: the memory buffer holding a kernel\'s launch arguments (plus hidden ones such as block size). Its address arrives in s[0:1]; code reads it with s_load. NVIDIA uses constant bank 0 instead.', links: [{ label: 'PTX and AMDGCN', href: '/learn/gpu-isa-ptx/#worked-example-one-kernel-source-to-silicon' }] },
  { id: 'running-max-m-running-sum', term: 'running max (m), running sum', aliases: ['l'], definition: 'The two per-row numbers FlashAttention\'s online softmax keeps while it streams key blocks: m is the largest score seen so far, l the sum of exp(score − m). Old l and output are rescaled by exp(m_old − m_new) when m grows.', links: [{ label: 'FlashAttention worked example', href: '/learn/flash-attention/#worked-example-one-query-row-three-blocks' }] },
];
